"""Private offline HSN source index explorer, no network or external assets."""
from __future__ import annotations
import argparse
import json
import pathlib

def build(index_file,out_file,manifest_file,pairs_file=None):
    idx=json.loads(pathlib.Path(index_file).read_text('utf8'))
    man=json.loads(pathlib.Path(manifest_file).read_text('utf8'))
    assert len(idx['nodes'])==1728 and len(idx['spheres'])==144 and len(idx['houses'])==12
    followups=[json.loads(line) for line in pathlib.Path(pairs_file).read_text('utf8').splitlines()] if pairs_file else []
    assert not followups or (len(followups)==1728 and len({f['followupId'] for f in followups})==1728)
    # JSON embedded inside application script, prevent accidental <script> termination
    data=json.dumps({'index':idx,'followups':followups,'metrics':{k:man[k] for k in ['pairEvaluations','externalPerspectiveEvaluations','nonzeroLexicalSignalsUnreviewed','epistemicMethodCrossPairsNoEquivalence','nodePassRecords','sphereReviewRecords','houseFollowups','houseSphereFollowups']}},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>ATLAS ONE • 1,728 Civilizational Circuit</title>
<style>
:root{--bg:#07101f;--glass:#111d32;--panel:#16253d;--line:#2a3f5e;--text:#f0f5ff;--muted:#a9bad4;--cyan:#78f0e5;--gold:#e9c889;--violet:#bcb0fa;--pink:#fa9cc7}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 10% 0%,#153655 0%,transparent 36%),radial-gradient(ellipse at 90% 5%,#2a2355 0%,transparent 40%),var(--bg);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text)}header{padding:36px clamp(18px,4vw,65px) 24px;border-bottom:1px solid var(--line)}.eyebrow{letter-spacing:.21em;font-weight:700;font-size:11px;color:var(--cyan)}h1{font-size:clamp(27px,4vw,48px);line-height:1.05;margin:8px 0 14px;letter-spacing:-.03em}h2{font-size:22px;line-height:1.15;margin:0 0 10px}h3{margin:2px 0 7px;font-size:17px}.lead{max-width:950px;color:var(--muted);font-size:15px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;max-width:1120px;margin:20px 0 0}.metric{border:1px solid var(--line);border-radius:12px;padding:13px 14px;background:#0a182c9e}.metric strong{font-size:23px;color:var(--cyan);display:block}.metric span{font-size:11px;color:var(--muted)}main{padding:25px clamp(18px,4vw,65px);max-width:1600px;margin:auto}.workspace{display:grid;grid-template-columns:minmax(240px,310px) minmax(0,1fr);gap:18px}.sidebar,.detail{background:#0c182bcc;border:1px solid var(--line);border-radius:16px;padding:18px}.sidebar{align-self:start;position:sticky;top:12px;max-height:92vh;overflow-y:auto}.tag{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}button,input{font:inherit}button{cursor:pointer;background:transparent;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:9px 11px;text-align:left}button:hover,button:focus-visible{outline:1px solid var(--cyan);border-color:var(--cyan)}.house-btn{display:block;width:100%;margin-top:5px;font-size:13px}.house-btn.active{background:#1c344b;border-color:#4cb8af;color:#9ffaf0}.chip{font-size:11px;border:1px solid #38526c;padding:4px 8px;border-radius:999px;color:var(--muted);display:inline-block;margin:4px 4px 0 0}.signal{color:var(--gold)}.hold{color:var(--pink)}.section{margin-bottom:23px}.spheregrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:9px;margin:13px 0}.sphere{background:var(--glass);min-height:107px;display:flex;flex-direction:column;gap:5px}.sphere.active{border-color:var(--cyan);background:#1c3545}.sphere small,.subtle{color:var(--muted);font-size:12px}.nodes{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:7px}.node{font-size:12px;min-height:57px;display:flex;flex-direction:column}.node.active{background:#2b3458;border-color:var(--violet)}.node .id{font-family:ui-monospace,monospace;color:var(--cyan);font-size:11px}input{background:#0a1426;border:1px solid var(--line);border-radius:9px;color:#fff;padding:11px 12px;width:100%;margin:10px 0}.review{border:1px solid #33536b;background:#0d253a;border-radius:11px;padding:15px;margin:10px 0}.review p{margin:7px 0;color:#d3e1ed}.candidate{display:block;border-top:1px solid var(--line);padding:8px 0;font-size:13px}.candidate:first-child{border-top:0}.risk{font-size:11px;color:var(--pink)}.copy{float:right;font-size:12px}.note{border-left:3px solid var(--gold);padding:9px 14px;background:#2a241c77;color:#e9dac5;margin:14px 0;font-size:13px}.muted{color:var(--muted)}.right{margin-top:13px}.count{color:var(--gold);font-size:12px}.mono{font-family:ui-monospace,monospace;overflow-wrap:anywhere;font-size:12px}footer{padding:25px;color:var(--muted);border-top:1px solid var(--line);font-size:12px}a{color:var(--cyan)}@media(max-width:850px){.workspace{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}header{padding-top:22px}}
</style></head><body><header><div class="eyebrow">ATLAS ONE / ARIADNE v0.7 • SOURCE-LOCKED RESEARCH</div><h1>1,728-dimensional<br/>civilizational circuit</h1><div class="lead">144 sphere perspectives × 1,728 original nodes. Cross-house lexical links are only review candidates. This is a real local computational sweep, not 1,728 independent resident turns or a deployed SwarmChat host.</div><div class="metrics" id="metrics"></div></header><main><div class="workspace"><aside class="sidebar"><div class="tag">Twelve houses</div><div id="houses"></div><p class="subtle">Independent House lenses, non-offsettable rights and source editions preserved. Select a house to explore.</p></aside><section class="detail"><div class="tag" id="viewtype">House</div><h2 id="title"></h2><div class="subtle" id="subtitle"></div><div class="note">Original Ariadne v0.7 source SHA256: <span class="mono">07533cf7a6b6f567259962bf73efee9b22b47cbacb429499787800e07864e5a6</span>. No accepted cross-domain equivalence, no CANON change, no resident auth, no automatic posting or deployment.</div><div class="section"><h3>Sphere perspectives</h3><div id="spheregrid" class="spheregrid"></div></div><div class="section"><div class="tag">Node browse</div><label for="search">Search source labels and HSN IDs</label><input id="search" placeholder="E.g. plasma, H01.S05.N09, epistemology, public health" autocomplete="off"/><div class="subtle" id="nodecount"></div><div id="nodegrid" class="nodes"></div></div><div class="section" id="selected"></div></section></div></main><footer>Local offline static reader • No external scripts or network • Original source bytes not included • Data and code verified separately. Fiction/Imagine integration is opt-in and explicitly non-empirical.</footer>
<script>
const DB=__DATA__;
const nodes=DB.index.nodes,spheres=DB.index.spheres,houses=DB.index.houses;
const byHouse=Object.fromEntries(houses.map(h=>[h.id,h]));
const bySphere=Object.fromEntries(spheres.map(s=>[s.id,s]));
const byNode=Object.fromEntries(nodes.map(n=>[n.id,n]));
let activeHouse='H01',activeSphere=null,activeNode=null;
const el=id=>document.getElementById(id);
function h(tag,cls,text){const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x}
function btn(label,onClick,cls=''){const x=h('button',cls,label);x.type='button';x.onclick=onClick;return x}
const fm=n=>Number(n||0).toLocaleString('en-US');
function init(){const met=[['Node reviews',1728],['Sphere sweeps',144],['Pair evaluations',DB.metrics.pairEvaluations],['House follow-ups',12]];met.forEach(([l,n])=>{const x=h('div','metric');x.append(h('strong','',fm(n)),h('span','',l));el('metrics').append(x)});el('search').addEventListener('input',()=>renderNodes());render()}
function render(){renderHouses();renderSpheres();renderNodes();renderSelected()}
function renderHouses(){const root=el('houses');root.replaceChildren();for(const item of houses){const x=btn(item.id+' · '+item.name,()=>{activeHouse=item.id;activeSphere=null;activeNode=null;el('search').value='';render()},'house-btn'+(activeHouse===item.id?' active':''));root.append(x)}
const curr=byHouse[activeHouse];el('title').textContent=curr.name;el('subtitle').textContent=curr.id+' · '+curr.perspective+' · 12 spheres · 144 original nodes · House review not ratified'}
function renderSpheres(){const root=el('spheregrid');root.replaceChildren();for(const item of spheres.filter(s=>s.houseId===activeHouse)){
const x=btn('',()=>{activeSphere=item.id;activeNode=null;el('search').value='';render()},'sphere'+(item.id===activeSphere?' active':''));x.append(h('span','mono',item.id),h('strong','',item.name),h('small','',`${item.topCandidates.length} shortlisted · DOMAIN ${item.roleCounts.DOMAIN_SPECIALIZATION||0} / META ${item.roleCounts.EPISTEMIC_META||0}`));root.append(x)}}
function renderNodes(){const root=el('nodegrid'),q=el('search').value.toLowerCase().trim();let shown=nodes.filter(n=>q?`${n.id} ${n.name}`.toLowerCase().includes(q):(activeSphere?n.sphereId===activeSphere:n.houseId===activeHouse));shown=shown.slice(0,180);root.replaceChildren();el('nodecount').textContent=`${shown.length} visible${q?' (search results, capped 180)':''} · no semantic acceptance`;for(const n of shown){const x=btn('',()=>{activeNode=n.id;activeSphere=n.sphereId;render();el('selected').scrollIntoView({block:'nearest',behavior:'smooth'})},'node'+(n.id===activeNode?' active':''));x.append(h('span','id',n.id),h('span','',n.name),h('small','subtle',n.kind==='EPISTEMIC_META'?'Method / meta lens':'Domain specialization'));root.append(x)}}
function renderSelected(){const root=el('selected');root.replaceChildren();if(activeNode){const n=byNode[activeNode],s=bySphere[n.sphereId];root.append(h('div','tag','Selected original node'),h('h3','',n.id+' · '+n.name),h('p','muted',`${s.name} · ${n.kind} · SOURCE_ONLY`));const div=h('div','review');div.append(h('strong','','Review-only adjacent perspectives'));if(!n.candidatePerspectives.length)div.append(h('p','muted','No stronger candidate after lexical and false-friend filters. This gap is preserved.'));
for(const c of n.candidatePerspectives){const x=h('div','candidate');x.append(h('b','',`${c.sphereId} · ${c.sphereName}`),h('span','risk',` · ${c.status}, ${c.reviewRisk}`));div.append(x)}root.append(div,h('div','mono',`Source node SHA256: ${n.nodeSHA256}`));return;}
if(activeSphere){const s=bySphere[activeSphere];root.append(h('div','tag','Sphere perspective'),h('h3','',s.id+' · '+s.name));const div=h('div','review');div.append(h('strong','','Cross-sphere lexical candidates (UNREVIEWED)'));if(!s.topCandidates.length)div.append(h('p','muted','No shortlisted candidates; no equivalence inferred.'));
for(const c of s.topCandidates){const b=h('div','candidate');b.append(h('span','mono',c.node+' · '),h('b','',c.nodeName),h('p','subtle',`${c.reviewRisk} · overlap: ${c.overlapTokens.join(', ')||'none'} · score is NOT probability`));div.append(b)}root.append(div);
const lens=h('div','review');lens.append(h('h3','','Twelve House follow-up perspectives'));const follow=DB.followups.filter(p=>p.sphereUnderReview===activeSphere);
if(follow.length!==12)lens.append(h('p','muted','House follow-ups are not embedded in this preview.'));
else for(const p of follow){const d=document.createElement('details');d.className='candidate';const sum=document.createElement('summary');sum.textContent=p.housePerspective+' · '+p.housePerspectiveName+(p.sphereRole==='EPISTEMIC_METHOD'?' · method lens':'');d.append(sum,h('p','subtle',p.question),h('p','risk',p.semanticGate+' · UNREVIEWED · no actual Macroturn'));lens.append(d)}
root.append(lens);return;}
const house=byHouse[activeHouse];root.append(h('div','tag','Twelve-House follow-up'),h('h3','',house.id+' — '+house.perspective),h('p','muted','A future specialist can challenge each sphere with exact sources, contradictions, native-unit physical stocks, accessibility and binding affected-party rights. No resident assigned by content volume.'))}
init();
</script></body></html>'''
    html=html.replace('__DATA__',data)
    pathlib.Path(out_file).write_text(html,encoding='utf8')
    return pathlib.Path(out_file).stat().st_size
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--index',required=True);p.add_argument('--manifest',required=True);p.add_argument('--pairs',required=False);p.add_argument('--out',required=True);a=p.parse_args();print(build(a.index,a.out,a.manifest,a.pairs))
